package model

// An attachment row tracks both a multipart session and its completed object.
// Storage keys are generated by the server and are never accepted from clients.
type Attachment struct {
	ID        string `gorm:"primaryKey;size:43"`
	NoteID    int32  `gorm:"not null;index"`
	Name      string `gorm:"size:255;not null"`
	Type      string `gorm:"size:64;not null"`
	Size      int64  `gorm:"not null"`
	ObjectKey string `gorm:"size:768;not null"`
	UploadID  string `gorm:"size:2048;not null"`
	Parts     string `gorm:"type:longtext"`
	Complete  bool   `gorm:"not null;default:false"`
	CreatedAt int64  `gorm:"autoCreateTime"`
}
